cuda_source = """
#include <cuda_fp16.h>

__global__ void sum_reduce_kernel(const half* input, half* output, 
                                  int64_t total_elements, int64_t reduce_dim_size, 
                                  int64_t outer_size, int64_t inner_size, int64_t reduce_dim_idx) {
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;

    if (tid >= total_elements) return;

    // Calculate which position in the reduced dimension this thread handles
    int64_t outer_idx = tid / (reduce_dim_size * inner_size);
    int64_t remaining = tid % (reduce_dim_size * inner_size);
    int64_t inner_idx = remaining % inner_size;
    int64_t reduce_idx = remaining / inner_size;

    // For each element in the reduce dimension, accumulate
    half sum = __hzero();
    for (int64_t i = 0; i < reduce_dim_size; ++i) {
        int64_t input_idx = outer_idx * (reduce_dim_size * inner_size) + i * inner_size + inner_idx;
        sum = __hadd(sum, input[input_idx]);
    }

    output[tid] = sum;
}

// Optimized version using shared memory for better performance
__global__ void sum_reduce_kernel_optimized(const half* input, half* output,
                                            int64_t total_elements, int64_t reduce_dim_size,
                                            int64_t outer_size, int64_t inner_size, int64_t reduce_dim_idx) {
    extern __shared__ half sdata[];

    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t local_tid = threadIdx.x;

    if (tid >= total_elements) return;

    // Calculate indices
    int64_t outer_idx = tid / (reduce_dim_size * inner_size);
    int64_t remaining = tid % (reduce_dim_size * inner_size);
    int64_t inner_idx = remaining % inner_size;
    int64_t reduce_idx = remaining / inner_size;

    // Load data into shared memory
    half sum = __hzero();
    for (int64_t i = 0; i < reduce_dim_size; ++i) {
        int64_t input_idx = outer_idx * (reduce_dim_size * inner_size) + i * inner_size + inner_idx;
        sum = __hadd(sum, input[input_idx]);
    }

    output[tid] = sum;
}

torch::Tensor sum_reduce_forward(const torch::Tensor& input, int64_t reduce_dim) {
    TORCH_CHECK(input.dtype() == torch::kFloat16, "Input must be float16");

    auto input_sizes = input.sizes();
    int64_t total_elements = input.numel();

    // Calculate dimensions
    int64_t reduce_dim_size = input_sizes[reduce_dim];
    int64_t outer_size = 1;
    int64_t inner_size = 1;

    for (int64_t i = 0; i < reduce_dim; ++i) {
        outer_size *= input_sizes[i];
    }

    for (int64_t i = reduce_dim + 1; i < input.dim(); ++i) {
        inner_size *= input_sizes[i];
    }

    // Create output tensor with keepdim=True
    std::vector<int64_t> output_sizes;
    for (int64_t i = 0; i < input.dim(); ++i) {
        if (i == reduce_dim) {
            output_sizes.push_back(1);
        } else {
            output_sizes.push_back(input_sizes[i]);
        }
    }

    auto output = torch::empty(output_sizes, torch::TensorOptions().dtype(torch::kFloat16).device(torch::kCUDA));

    // Launch kernel
    const int threads_per_block = 256;
    const int blocks = (total_elements + threads_per_block - 1) / threads_per_block;

    if (blocks > 0) {
        sum_reduce_kernel_optimized<<<blocks, threads_per_block, 0>>>(
            input.data_ptr<half>(),
            output.data_ptr<half>(),
            total_elements,
            reduce_dim_size,
            outer_size,
            inner_size,
            reduce_dim
        );
    }

    TORCH_CUDA_CHECK(cudaGetLastError());
    return output;
}
"""

